bool hugetlb_file_has_reservation(struct inode *inode, pgoff_t idx)
{
	struct resv_map *resv = inode_resv_map(inode);
	long needed;
	long chg;

	if (!resv)
		return false;

	spin_lock(&resv->lock);
	chg = add_reservation_in_range(resv, idx, idx + 1, NULL, NULL, &needed);
	spin_unlock(&resv->lock);

	return chg == 0;
}
EXPORT_SYMBOL_GPL(hugetlb_file_has_reservation);

